    #include <iostream>
#include <vector>
using namespace std;

class Node {
public:
    int data;
    Node* next;

    Node(int x) {
        data = x;
        next = nullptr;
    }
};

Node* mergeKLists(vector<Node*>& lists) {
    Node dummy(0);
    Node* tail = &dummy;

    while (true) {
        int minIndex = -1;

        // Find the minimum current node
        for (int i = 0; i < lists.size(); i++) {
            if (lists[i] != nullptr &&
                (minIndex == -1 ||
                 lists[i]->data < lists[minIndex]->data)) {
                minIndex = i;
            }
        }

        if (minIndex == -1)
            break;

        tail->next = lists[minIndex];
        tail = tail->next;

        lists[minIndex] = lists[minIndex]->next;
    }

    return dummy.next;
}

int main() {
    vector<Node*> lists(3);

    lists[0] = new Node(1);
    lists[0]->next = new Node(4);
    lists[0]->next->next = new Node(7);

    lists[1] = new Node(2);
    lists[1]->next = new Node(8);

    lists[2] = new Node(3);
    lists[2]->next = new Node(9);

    Node* result = mergeKLists(lists);

    while (result) {
        cout << result->data;
        if (result->next)
            cout << " -> ";
        result = result->next;
    }

    return 0;
}


