};

Node* mergeTwoLists(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;

    while (a && b) {
        if (a->data <= b->data) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }

        tail = tail->next;
    }

    if (a)
        tail->next = a;
    else
        tail->next = b;

    return dummy.next;
}

Node* mergeRange(vector<Node*>& lists, int left, int right) {
    if (left > right)
        return nullptr;

    if (left == right)
        return lists[left];

    int mid = left + (right - left) / 2;

    Node* first = mergeRange(lists, left, mid);
    Node* second = mergeRange(lists, mid + 1, right);

    return mergeTwoLists(first, second);
}

Node* mergeKLists(vector<Node*>& lists) {
    if (lists.empty())
        return nullptr;

    return mergeRange(lists, 0, lists.size() - 1);
}

